class Solution {

    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        String text = serialize(root),
            pattern = serialize(subRoot);
        return kmpContains(text, pattern);
    }

    private String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        build(root, sb);
        return sb.toString();
    }

    private void build(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append(",#");
            return;
        }
        sb.append(',').append(node.val); // leading ',' stops "2" matching inside "12"
        build(node.left, sb);
        build(node.right, sb);
    }

    private boolean kmpContains(String text, String pat) {
        int[] lps = new int[pat.length()];
        for (int i = 1, len = 0; i < pat.length(); ) {
            // build longest-prefix-suffix table
            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, j = 0; i < text.length(); ) {
            // scan text
            if (text.charAt(i) == pat.charAt(j)) {
                i++;
                j++;
                if (j == pat.length()) return true;
            } else if (j > 0) j = lps[j - 1];
            else i++;
        }
        return false;
    }
}

