class Solution {

    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        dfs(root, 0, result, true);
        return result;
    }

    public List<Integer> leftSideView(TreeNode root) {
        // Striver's left view
        List<Integer> result = new ArrayList<>();
        dfs(root, 0, result, false);
        return result;
    }

    private void dfs(
        TreeNode node,
        int depth,
        List<Integer> result,
        boolean rightFirst
    ) {
        if (node == null) return;
        if (depth == result.size()) result.add(node.val); // first node reached at this depth
        TreeNode first = rightFirst ? node.right : node.left;
        TreeNode second = rightFirst ? node.left : node.right;
        dfs(first, depth + 1, result, rightFirst);
        dfs(second, depth + 1, result, rightFirst);
    }
}

