class Solution {

    public int goodNodes(TreeNode root) {
        return dfs(root, new ArrayList<>());
    }

    private int dfs(TreeNode node, List<Integer> path) {
        if (node == null) return 0;
        boolean good = true;
        for (int v : path)
            if (v > node.val) {
                good = false;
                break;
            } // scan ancestors
        path.add(node.val);
        int count =
            (good ? 1 : 0) +
            dfs(node.left, path) +
            dfs(node.right, path);
        path.remove(path.size() - 1); // backtrack
        return count;
    }
}

