class Solution {
    public boolean isValidBST(TreeNode root) {
        if (root == null) return true;
        if (root.left != null && maxOf(root.left) >= root.val) return false;    // whole left subtree must be
        smaller
        if (root.right != null && minOf(root.right) <= root.val) return false; // whole right subtree must
        be larger
        return isValidBST(root.left) && isValidBST(root.right);
    }

    private int maxOf(TreeNode n) {
        int m = n.val;
        if (n.left != null) m = Math.max(m, maxOf(n.left));
        if (n.right != null) m = Math.max(m, maxOf(n.right));
        return m;
    }

    private int minOf(TreeNode n) {
        int m = n.val;
        if (n.left != null) m = Math.min(m, minOf(n.left));
        if (n.right != null) m = Math.min(m, minOf(n.right));
        return m;

    }
}

