class Solution {

    public boolean isValidBST(TreeNode root) {
        return valid(root, Long.MIN_VALUE, Long.MAX_VALUE); // long avoids edge cases at int limits
    }

    private boolean valid(TreeNode node, long low, long high) {
        if (node == null) return true;
        if (node.val <= low || node.val >= high) return false; // outside allowed open interval
        return (
            valid(node.left, low, node.val) && // left: tighten upper bound
            valid(node.right, node.val, high)
        ); // right: tighten lower bound
    }
}

