class Solution {

    public int kthSmallest(TreeNode root, int k) {
        List<Integer> vals = new ArrayList<>();
        collect(root, vals);
        Collections.sort(vals); // ignores the BST order entirely
        return vals.get(k - 1); // kth largest: vals.get(vals.size() - k)
