class Solution {

    private Map<Integer, Integer> inIndex;
    private int preIdx;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        inIndex = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) inIndex.put(
            inorder[i],
            i
        ); // O(1) root lookup
        preIdx = 0;
        return build(preorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int lo, int hi) {
        if (lo > hi) return null; // empty inorder range
        int rootVal = preorder[preIdx++]; // next preorder value is this subtree's root
        TreeNode root = new TreeNode(rootVal);
        int mid = inIndex.get(rootVal);
        root.left = build(preorder, lo, mid - 1); // must build left first (preorder order)
        root.right = build(preorder, mid + 1, hi);
        return root;
    }
}

