class Solution {

    public int maxPathSum(TreeNode root) {
        if (root == null) return Integer.MIN_VALUE;
        int through =
            root.val +
            Math.max(0, gain(root.left)) +
            Math.max(0, gain(root.right));
        return Math.max(
            through,
            Math.max(maxPathSum(root.left), maxPathSum(root.right))
        );
    }

    // best downward path sum starting at node (recomputed every time = the inefficiency)
    private int gain(TreeNode node) {
        if (node == null) return 0;
        return (
            node.val +
            Math.max(0, Math.max(gain(node.left), gain(node.right)))
        );
    }
}

