class Solution {

    private int best;

    public int maxPathSum(TreeNode root) {
        best = Integer.MIN_VALUE; // not 0: all-negative trees must return a negative answer
        dfs(root);
        return best;
    }

    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int leftGain = Math.max(0, dfs(node.left)); // drop negative branches
        int rightGain = Math.max(0, dfs(node.right));
        best = Math.max(best, node.val + leftGain + rightGain); // path that turns at this node
        return node.val + Math.max(leftGain, rightGain); // parent can extend only one branch
    }
}

