public class Codec {

    public String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        write(root, sb);
        return sb.toString();
    }

    private void write(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append("#,");
            return;
        } // null marker makes preorder unambiguous
        sb.append(node.val).append(',');
        write(node.left, sb);
        write(node.right, sb);
    }

    private int pos;

    public TreeNode deserialize(String data) {
        String[] tokens = data.split(",");
        pos = 0;
        return read(tokens);
    }

    private TreeNode read(String[] tokens) {
        String t = tokens[pos++];
        if (t.equals("#")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(t));
        node.left = read(tokens); // same order as write: node, left, right
        node.right = read(tokens);
        return node;
    }
}

