class Solution {

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        List<TreeNode> level = new ArrayList<>();
        level.add(root);
        int best = 0;
        while (!level.isEmpty()) {
            best = Math.max(best, level.size()); // already trimmed, so size = width
            List<TreeNode> next = new ArrayList<>();
            for (TreeNode node : level) {
                // nulls produce two null placeholders
                next.add(node == null ? null : node.left);
                next.add(node == null ? null : node.right);
            }
            int lo = 0,
                hi = next.size() - 1;
            while (lo <= hi && next.get(lo) == null) lo++; // trim leading nulls
            while (hi >= lo && next.get(hi) == null) hi--; // trim trailing nulls
            level =
                lo > hi
                    ? new ArrayList<>()
                    : new ArrayList<>(next.subList(lo, hi + 1));
        }
        return best;
    }
}

