class Solution {

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        Deque<TreeNode> nodes = new ArrayDeque<>();
        Deque<Long> idxs = new ArrayDeque<>();
        nodes.offer(root);
        idxs.offer(0L);
        long best = 0;
        while (!nodes.isEmpty()) {
            int size = nodes.size();
            long first = idxs.peek(); // leftmost index on this level
            long last = 0;
            for (int k = 0; k < size; k++) {
                TreeNode node = nodes.poll();

                long i = idxs.poll() - first; // normalize so the level starts at 0
                last = i;
                if (node.left != null) {
                    nodes.offer(node.left);
                    idxs.offer(2 * i + 1);
                }
                if (node.right != null) {
                    nodes.offer(node.right);
                    idxs.offer(2 * i + 2);
                }
            }
            best = Math.max(best, last + 1); // width = last - 0 + 1
        }
        return (int) best;
    }
}

